content:
Looking at the existing dev and prod infra setups, I need to create two new files that follow the same pattern as the existing `assets` and `reader` declarations.

The key details:
- **Dev**: account-based trust with programmatic access
- **Prod**: OIDC trust with pod identity association
- **Both**: use `SecureBucket` for the logs bucket and `ReaderIam` for the scoped reader identity, adding `s3:PutObject` via `additionalActions`

`src/envs/dev/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  programmaticAccess: true,
  additionalActions: ["s3:PutObject"],
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
});
```

These files will be automatically discovered and built by `chant build src/envs/{dev,prod}/infra` alongside the existing `main.ts`, creating the logs bucket and scoped reader identity for each environment with the correct S3 permissions (GetObject via baseline policy + PutObject via `additionalActions`).
